std::complex<double> fzip(double s12, double s34, double s56) {
  using namespace constants_mod;

  double Del12 = s12 - s34 - s56;
  double Del34 = s34 - s12 - s56;
  double Del56 = s56 - s12 - s34;
  double Del3 = s12*Del12 + s34*Del34 + s56*Del56;

  // @coverage-probe
  std::complex<double> fzip_value =
      ((3.0*s34*Del34/pow(Del3,2) - 1.0/Del3)*s12*s56) * i3m(s12,s34,s56)
    + ((3.0*s56*Del56/pow(Del3,2) - 0.5/Del3)*s12) * lnrat(-s12,-s34)
    + ((3.0*s12*Del12/pow(Del3,2) - 0.5/Del3)*s56) * lnrat(-s56,-s34)
    - cplx2(0.5*Del34/Del3, zip);

  return fzip_value;
}

